INSERT INTO "homepage_sections" ("id", "type", "title_ar", "title_en", "language", "sort_order", "visible", "metadata", "created_at", "updated_at") VALUES ('e22c8a9d-d7d6-4027-ba40-dc63be21e9b5', 'product_slider', 'الاكثر مبيعا', 'Best Sellers', 'both', 3, FALSE, '"{\"products\":[{\"handle\":\"ugreen-100w-foldable-solar-panel-monocrystalline\",\"titleEn\":\"UGREEN 100W Foldable Solar Panel - High-Efficiency Monocrystalline Charger for Portable Power Stations\",\"titleAr\":\"UGREEN 100W Foldable Solar Panel - High-Efficiency Monocrystalline Charger for Portable Power Stations\",\"vendor\":\"UGREEN\",\"imageUrl\":\"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/UGREEN20_000mAhPowerBank30WPDFastChargingwithBuilt-inUSB-CCable_DigitalDisplay_78.png?v=1772874744\",\"price\":\"190.0\",\"compareAtPrice\":\"199\",\"currency\":\"JOD\",\"description\":\"Harness the power of the sun with the UGREEN 100W Solar Panel. Featuring high-efficiency monocrystalline cells and a foldable, portable design, this solar charger is the perfect companion for your outdoor adventures and off-grid power needs. The UGREEN 100W Solar Panel is engineered for maximum energy conversion. Using advanced monocrystalline silicon cells, it boasts a high conversion efficiency of up to 23%, allowing you to recharge your portable power stations faster even on cloudy days. It is designed to work seamlessly with UGREEN PowerRoam stations and most third-party solar generators. Built for the rugged outdoors, this solar panel features an IP67 waterproof rating, protecting it from sudden rain or water splashes during camping or hiking. The foldable kickstand allows you to adjust the panel to the perfect angle (45° or 55°) to capture maximum sunlight throughout the day. Portability is key with the UGREEN 100W. It features a fold-and-go design with a built-in magnetic handle, making it easy to carry like a briefcase. Whether you are overlanding, fishing, or preparing for an emergency power backup at home, this solar panel provides a clean, reliable, and sustainable energy source. Key Features 100W Solar Power: Reliable energy output to keep your power stations charged off-grid. 23% High Efficiency: Monocrystalline cells capture more sunlight for faster charging. IP67 Waterproof: Durable, weather-resistant build designed for outdoor environments. Adjustable Kickstands: Easily tilt the panel to find the best angle for solar absorption. Foldable & Portable: Compact design with a magnetic handle for effortless transport. Universal Compatibility: Works with UGREEN PowerRoam and most solar generators via standard connectors.\",\"descriptionAr\":\"Harness the power of the sun with the UGREEN 100W Solar Panel. Featuring high-efficiency monocrystalline cells and a foldable, portable design, this solar charger is the perfect companion for your outdoor adventures and off-grid power needs. The UGREEN 100W Solar Panel is engineered for maximum energy conversion. Using advanced monocrystalline silicon cells, it boasts a high conversion efficiency of up to 23%, allowing you to recharge your portable power stations faster even on cloudy days. It is designed to work seamlessly with UGREEN PowerRoam stations and most third-party solar generators. Built for the rugged outdoors, this solar panel features an IP67 waterproof rating, protecting it from sudden rain or water splashes during camping or hiking. The foldable kickstand allows you to adjust the panel to the perfect angle (45° or 55°) to capture maximum sunlight throughout the day. Portability is key with the UGREEN 100W. It features a fold-and-go design with a built-in magnetic handle, making it easy to carry like a briefcase. Whether you are overlanding, fishing, or preparing for an emergency power backup at home, this solar panel provides a clean, reliable, and sustainable energy source. Key Features 100W Solar Power: Reliable energy output to keep your power stations charged off-grid. 23% High Efficiency: Monocrystalline cells capture more sunlight for faster charging. IP67 Waterproof: Durable, weather-resistant build designed for outdoor environments. Adjustable Kickstands: Easily tilt the panel to find the best angle for solar absorption. Foldable & Portable: Compact design with a magnetic handle for effortless transport. Universal Compatibility: Works with UGREEN PowerRoam and most solar generators via standard connectors.\"},{\"handle\":\"anker-solix-f2600-portable-power-station-2560wh-3600w\",\"titleEn\":\"Anker SOLIX F2600 Portable Power Station - 2560Wh Capacity & 3600W AC Output (GaNPrime)\",\"titleAr\":\"Anker SOLIX F2600 Portable Power Station - 2560Wh Capacity & 3600W AC Output (GaNPrime)\",\"vendor\":\"Anker\",\"imageUrl\":\"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/UGREEN20_000mAhPowerBank30WPDFastChargingwithBuilt-inUSB-CCable_DigitalDisplay_93.png?v=1772875972\",\"price\":\"1990.0\",\"compareAtPrice\":\"1990\",\"currency\":\"JOD\",\"description\":\"Take control of your home backup and outdoor adventures with the Anker SOLIX F2600. Featuring a massive 2560Wh capacity and a high-performance 3600W AC output powered by GaNPrime technology, this portable power station is built to run heavy-duty appliances and power your life for a decade. The Anker SOLIX F2600 is a true powerhouse. With its 3600W AC output, it can simultaneously power multiple heavy appliances, including portable air conditioners, electric grills, and power tools. The 2560Wh capacity ensures that your refrigerator stays running for hours during a blackout or provides days of energy for off-grid camping. Efficiency is redefined with GaNPrime technology, which reduces energy loss and ensures the unit stays cool during high-output sessions. Recharging is incredibly fast; thanks to HyperFlash™ technology, the F2600 can be fully recharged via a wall outlet in approximately 2 hours. It also supports 1000W Solar Input, allowing you to top up using the sun in just 3 to 4 hours. Designed for durability and ease of use, the SOLIX F2600 features an integrated suitcase-style handle and wheels, making it easy to move despite its heavy-duty build. It uses premium LiFePO4 batteries rated for 3,000 cycles, offering a 10-year lifespan. Plus, with the Anker Smart App, you can track performance and control every port directly from your smartphone. Key Features 3600W Powerful AC Output: High-wattage pure sine wave inverter to run 99% of household appliances. Massive 2560Wh Capacity: Professional-grade energy storage for home backup and long-term off-grid use. GaNPrime Technology: More efficient energy conversion and cooler operation for a longer-lasting device. 10-Year Full Device Lifespan: Powered by EV-grade LiFePO4 batteries with 3,000+ charge cycles. Ultra-Fast Recharging: Full AC recharge in 2 hours and support for 1000W solar input. Portable Suitcase Design: Built-in wheels and telescopic handle for effortless mobility on any terrain. UPS Functionality: Instant power switch (under 20ms) to protect your computers and medical devices.\",\"descriptionAr\":\"Take control of your home backup and outdoor adventures with the Anker SOLIX F2600. Featuring a massive 2560Wh capacity and a high-performance 3600W AC output powered by GaNPrime technology, this portable power station is built to run heavy-duty appliances and power your life for a decade. The Anker SOLIX F2600 is a true powerhouse. With its 3600W AC output, it can simultaneously power multiple heavy appliances, including portable air conditioners, electric grills, and power tools. The 2560Wh capacity ensures that your refrigerator stays running for hours during a blackout or provides days of energy for off-grid camping. Efficiency is redefined with GaNPrime technology, which reduces energy loss and ensures the unit stays cool during high-output sessions. Recharging is incredibly fast; thanks to HyperFlash™ technology, the F2600 can be fully recharged via a wall outlet in approximately 2 hours. It also supports 1000W Solar Input, allowing you to top up using the sun in just 3 to 4 hours. Designed for durability and ease of use, the SOLIX F2600 features an integrated suitcase-style handle and wheels, making it easy to move despite its heavy-duty build. It uses premium LiFePO4 batteries rated for 3,000 cycles, offering a 10-year lifespan. Plus, with the Anker Smart App, you can track performance and control every port directly from your smartphone. Key Features 3600W Powerful AC Output: High-wattage pure sine wave inverter to run 99% of household appliances. Massive 2560Wh Capacity: Professional-grade energy storage for home backup and long-term off-grid use. GaNPrime Technology: More efficient energy conversion and cooler operation for a longer-lasting device. 10-Year Full Device Lifespan: Powered by EV-grade LiFePO4 batteries with 3,000+ charge cycles. Ultra-Fast Recharging: Full AC recharge in 2 hours and support for 1000W solar input. Portable Suitcase Design: Built-in wheels and telescopic handle for effortless mobility on any terrain. UPS Functionality: Instant power switch (under 20ms) to protect your computers and medical devices.\"},{\"handle\":\"anker-solix-c1000-gen2-portable-power-station-1056wh\",\"titleEn\":\"Anker SOLIX C1000 Gen 2 Portable Power Station - 1056Wh Capacity & 2100W AC Output\",\"titleAr\":\"Anker SOLIX C1000 Gen 2 Portable Power Station - 1056Wh Capacity & 2100W AC Output\",\"vendor\":\"Anker\",\"imageUrl\":\"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/UGREEN20_000mAhPowerBank30WPDFastChargingwithBuilt-inUSB-CCable_DigitalDisplay_84.png?v=1772875219\",\"price\":\"1250.0\",\"compareAtPrice\":\"1300\",\"currency\":\"JOD\",\"description\":\"Power your lifestyle with the Anker SOLIX C1000 Gen 2. Featuring a massive 1056Wh capacity and 2100W AC output, this next-generation portable power station uses LiFePO4 batteries to deliver safe, reliable energy for home backup, camping, and off-grid living. The Anker SOLIX C1000 Gen 2 is built to handle your most demanding appliances. With its 2100W AC output (Surge up to 3100W), it can easily power 99% of home devices, from coffee makers and blenders to power tools and full-sized refrigerators. Its 1056Wh capacity ensures your essentials stay running during long power outages or outdoor trips. Time is of the essence, which is why the C1000 Gen 2 features HyperFlash™ technology. It can recharge from 0 to 100% in just 58 minutes when plugged into a wall outlet. For off-grid enthusiasts, the integrated 600W Solar Input allows you to fully recharge via solar panels in roughly 1.8 hours under ideal conditions, making it a truly sustainable energy solution. Designed for longevity, this power station utilizes EV-grade LiFePO4 batteries that last for over 3,000 cycles (up to 10 years of daily use). With the Anker Smart App, you can monitor power usage, adjust charging speeds, and control settings remotely via Bluetooth or Wi-Fi. Its rugged, unibody design is built to withstand the bumps and drops of any adventure. Key Features 2100W Pure Sine Wave Output: Safely powers sensitive electronics and heavy-duty appliances. 1056Wh Massive Capacity: High-density energy storage for home backup and outdoor use. Ultra-Fast HyperFlash™ Charging: Recharges to 100% in just 58 minutes via AC wall outlet. 10-Year Lifespan: Powered by LiFePO4 batteries with 3,000+ charge cycles. 600W Solar Input: Fast green recharging for off-grid living and camping. UPS Functionality: Switches to battery power in less than 20ms during an outage. Smart App Control: Manage and monitor your power usage in real-time from your phone.\",\"descriptionAr\":\"Power your lifestyle with the Anker SOLIX C1000 Gen 2. Featuring a massive 1056Wh capacity and 2100W AC output, this next-generation portable power station uses LiFePO4 batteries to deliver safe, reliable energy for home backup, camping, and off-grid living. The Anker SOLIX C1000 Gen 2 is built to handle your most demanding appliances. With its 2100W AC output (Surge up to 3100W), it can easily power 99% of home devices, from coffee makers and blenders to power tools and full-sized refrigerators. Its 1056Wh capacity ensures your essentials stay running during long power outages or outdoor trips. Time is of the essence, which is why the C1000 Gen 2 features HyperFlash™ technology. It can recharge from 0 to 100% in just 58 minutes when plugged into a wall outlet. For off-grid enthusiasts, the integrated 600W Solar Input allows you to fully recharge via solar panels in roughly 1.8 hours under ideal conditions, making it a truly sustainable energy solution. Designed for longevity, this power station utilizes EV-grade LiFePO4 batteries that last for over 3,000 cycles (up to 10 years of daily use). With the Anker Smart App, you can monitor power usage, adjust charging speeds, and control settings remotely via Bluetooth or Wi-Fi. Its rugged, unibody design is built to withstand the bumps and drops of any adventure. Key Features 2100W Pure Sine Wave Output: Safely powers sensitive electronics and heavy-duty appliances. 1056Wh Massive Capacity: High-density energy storage for home backup and outdoor use. Ultra-Fast HyperFlash™ Charging: Recharges to 100% in just 58 minutes via AC wall outlet. 10-Year Lifespan: Powered by LiFePO4 batteries with 3,000+ charge cycles. 600W Solar Input: Fast green recharging for off-grid living and camping. UPS Functionality: Switches to battery power in less than 20ms during an outage. Smart App Control: Manage and monitor your power usage in real-time from your phone.\"},{\"handle\":\"anker-solix-c300-dc-portable-power-station-288wh-90000mah\",\"titleEn\":\"Anker SOLIX C300 DC Portable Power Station - 90,000mAh (288Wh) Capacity - 300W Max Output - LiFePO4 Battery - Smart App Control - Integrated LED Light - Grey\",\"titleAr\":\"Anker SOLIX C300 DC Portable Power Station - 90,000mAh (288Wh) Capacity - 300W Max Output - LiFePO4 Battery - Smart App Control - Integrated LED Light - Grey\",\"vendor\":\"Anker\",\"imageUrl\":\"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/C300X_aeb9283e-a4dd-4321-bccd-fa8700b73108.webp?v=1769626456\",\"price\":\"299.0\",\"compareAtPrice\":\"299\",\"currency\":\"JOD\",\"description\":\"The Anker SOLIX C300 DC is a compact and versatile portable power station designed for outdoor adventures and emergency backup. With a high-capacity 90,000mAh LiFePO4 battery and 300W total output, it features a unique wearable design and an integrated pop-up LED light for ultimate convenience. Power your lifestyle anywhere with the Anker SOLIX C300 DC. This portable powerhouse features a 288Wh capacity using ultra-durable LiFePO4 cells that last up to 10 years, even with daily use. Its vertical, compact design is 15% smaller than similar power stations, and with the included shoulder strap, it is easy to carry on hikes, camping trips, or between job sites. Equipped with 7 versatile ports, including two 140W USB-C ports, the C300 DC can fast-charge laptops, smartphones, and even small appliances simultaneously. The integrated smart app connectivity via Bluetooth or Wi-Fi allows you to monitor power levels and control the built-in 3-level LED light remotely. Whether you are navigating a blackout or charging gear in the wild, the SOLIX C300 ensures you stay connected with safe, stable, and long-lasting power. Key Features High-Capacity 288Wh: Large 90,000mAh capacity provides multiple charges for laptops and mobile devices. LiFePO4 Long-Life Battery: Durable battery chemistry designed for over 3,000 charge cycles and a 10-year lifespan. Ultra-Fast 140W USB-C: Dual high-speed ports capable of charging a MacBook Pro to 50% in record time. Compact & Wearable: Vertical space-saving design with a built-in handle and included shoulder strap for portability. Smart App Control: Monitor real-time power usage and customize settings via the Anker App. Built-In Emergency Light: Features a pop-up LED light with adjustable brightness for night use. Technical Specifications Brand Anker SOLIX Model C300 DC (A17B1) Capacity 288Wh / 90,000mAh Battery Type LiFePO4 (Lithium Iron Phosphate) Total Output 300W Max USB-C Output Up to 140W (PD 3.1) Charging Inputs USB-C (140W) / Solar (100W) / Car Socket\",\"descriptionAr\":\"The Anker SOLIX C300 DC is a compact and versatile portable power station designed for outdoor adventures and emergency backup. With a high-capacity 90,000mAh LiFePO4 battery and 300W total output, it features a unique wearable design and an integrated pop-up LED light for ultimate convenience. Power your lifestyle anywhere with the Anker SOLIX C300 DC. This portable powerhouse features a 288Wh capacity using ultra-durable LiFePO4 cells that last up to 10 years, even with daily use. Its vertical, compact design is 15% smaller than similar power stations, and with the included shoulder strap, it is easy to carry on hikes, camping trips, or between job sites. Equipped with 7 versatile ports, including two 140W USB-C ports, the C300 DC can fast-charge laptops, smartphones, and even small appliances simultaneously. The integrated smart app connectivity via Bluetooth or Wi-Fi allows you to monitor power levels and control the built-in 3-level LED light remotely. Whether you are navigating a blackout or charging gear in the wild, the SOLIX C300 ensures you stay connected with safe, stable, and long-lasting power. Key Features High-Capacity 288Wh: Large 90,000mAh capacity provides multiple charges for laptops and mobile devices. LiFePO4 Long-Life Battery: Durable battery chemistry designed for over 3,000 charge cycles and a 10-year lifespan. Ultra-Fast 140W USB-C: Dual high-speed ports capable of charging a MacBook Pro to 50% in record time. Compact & Wearable: Vertical space-saving design with a built-in handle and included shoulder strap for portability. Smart App Control: Monitor real-time power usage and customize settings via the Anker App. Built-In Emergency Light: Features a pop-up LED light with adjustable brightness for night use. Technical Specifications Brand Anker SOLIX Model C300 DC (A17B1) Capacity 288Wh / 90,000mAh Battery Type LiFePO4 (Lithium Iron Phosphate) Total Output 300W Max USB-C Output Up to 140W (PD 3.1) Charging Inputs USB-C (140W) / Solar (100W) / Car Socket\"},{\"handle\":\"anker-solix-c300x-portable-power-station-shoulder-bag-288wh\",\"titleEn\":\"Anker SOLIX C300X Portable Power Station - 288Wh Capacity & 300W AC Output (Compact Shoulder Bag Design)\",\"titleAr\":\"Anker SOLIX C300X Portable Power Station - 288Wh Capacity & 300W AC Output (Compact Shoulder Bag Design)\",\"vendor\":\"Anker\",\"imageUrl\":\"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/Anker-SOLIX-C300X-Portable-Power-Station-Sockets-1100x1100.webp?v=1772907352\",\"price\":\"319.0\",\"compareAtPrice\":\"350\",\"currency\":\"JOD\",\"description\":\"Take your power to go with the Anker SOLIX C300X. This ultra-portable power station features a unique shoulder-bag design, a 288Wh capacity, and a 300W AC output, making it the perfect lightweight companion for photography, remote work, and outdoor trips. The Anker SOLIX C300X redefines what it means to be portable. With its built-in shoulder strap and compact form factor, it’s designed to be carried as easily as a small bag. Despite its size, it delivers a steady 300W AC output (Surge up to 600W), allowing you to charge your laptop, camera gear, drones, and small portable appliances anywhere. Equipped with HyperFlash™ technology, the C300X can be recharged to 80% in just 50 minutes when plugged into a wall outlet. For the modern professional, it features dual 140W USB-C ports, capable of fast-charging two high-end laptops simultaneously at full speed. Safety and durability are at the core of the C300X. It utilizes long-lasting LiFePO4 batteries that maintain their health for over 3,000 cycles (up to 10 years of use). With smart app control via Bluetooth and Wi-Fi, you can monitor your energy usage and toggle settings on the fly. It even features a built-in LED light with multiple modes, making it an essential tool for camping or emergency kits. Key Features Compact Shoulder-Bag Design: Extremely easy to carry with an integrated strap for hands-free mobility. 300W Pure Sine Wave AC Output: Safely powers laptops, monitors, and small electronics. 288Wh Capacity: Reliable energy storage for drones, cameras, and long work sessions outdoors. Dual 140W PD USB-C Ports: Blazing-fast charging for two laptops at once without an adapter. LiFePO4 Long-Life Batteries: High-grade cells designed for 10 years of daily reliability. 50-Minute Rapid Recharge: Get back to full power quickly with Anker''s HyperFlash technology. Integrated LED Light: Built-in lighting for camping, hiking, or power outages.\",\"descriptionAr\":\"Take your power to go with the Anker SOLIX C300X. This ultra-portable power station features a unique shoulder-bag design, a 288Wh capacity, and a 300W AC output, making it the perfect lightweight companion for photography, remote work, and outdoor trips. The Anker SOLIX C300X redefines what it means to be portable. With its built-in shoulder strap and compact form factor, it’s designed to be carried as easily as a small bag. Despite its size, it delivers a steady 300W AC output (Surge up to 600W), allowing you to charge your laptop, camera gear, drones, and small portable appliances anywhere. Equipped with HyperFlash™ technology, the C300X can be recharged to 80% in just 50 minutes when plugged into a wall outlet. For the modern professional, it features dual 140W USB-C ports, capable of fast-charging two high-end laptops simultaneously at full speed. Safety and durability are at the core of the C300X. It utilizes long-lasting LiFePO4 batteries that maintain their health for over 3,000 cycles (up to 10 years of use). With smart app control via Bluetooth and Wi-Fi, you can monitor your energy usage and toggle settings on the fly. It even features a built-in LED light with multiple modes, making it an essential tool for camping or emergency kits. Key Features Compact Shoulder-Bag Design: Extremely easy to carry with an integrated strap for hands-free mobility. 300W Pure Sine Wave AC Output: Safely powers laptops, monitors, and small electronics. 288Wh Capacity: Reliable energy storage for drones, cameras, and long work sessions outdoors. Dual 140W PD USB-C Ports: Blazing-fast charging for two laptops at once without an adapter. LiFePO4 Long-Life Batteries: High-grade cells designed for 10 years of daily reliability. 50-Minute Rapid Recharge: Get back to full power quickly with Anker''s HyperFlash technology. Integrated LED Light: Built-in lighting for camping, hiking, or power outages.\"},{\"handle\":\"anker-solix-c200-dc-portable-power-station-jordan\",\"titleEn\":\"Anker SOLIX C200 DC Portable Power Station - 185Wh Capacity, 100W Fast Charging, LiFePO4 Battery, Dark Gray - A17270Z1\",\"titleAr\":\"Anker SOLIX C200 DC Portable Power Station - 185Wh Capacity, 100W Fast Charging, LiFePO4 Battery, Dark Gray - A17270Z1\",\"vendor\":\"Anker\",\"imageUrl\":\"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/1_f2336d6e-e34a-4d29-8bdd-2eabd96c2c3e.webp?v=1747607000\",\"price\":\"139.0\",\"compareAtPrice\":\"139\",\"currency\":\"JOD\",\"description\":\"Enjoy reliable power anywhere with the Anker SOLIX C200 DC Portable Power Station. With durable LiFePO4 batteries and a compact design, this station provides continuous energy for your smartphones, cameras, and laptops, making it the perfect companion for trips and outdoor adventures. The Anker SOLIX C200 DC features advanced LiFePO4 battery technology that lasts up to 10 years of daily use, offering exceptional safety and sustainability. With a 185Wh capacity, it gives you the power to charge your devices multiple times, while the 100W USB-C port ensures ultra-fast charging for laptops and phones. The device is designed to be portable and lightweight, featuring a smart display that shows remaining power and charging speeds. Additionally, the station supports solar charging, allowing you to recharge in locations without traditional power sources, so you always stay connected. Key Features Long-Lasting LiFePO4 Battery: 10-year lifespan with consistent high performance. 100W Fast Charging: Bi-directional USB-C port charges your devices and the station itself rapidly. 185Wh Capacity: Ample power to charge phones, tablets, and cameras for several days. Compact & Durable Design: Lightweight with a robust build to withstand outdoor impacts. Multiple Inputs/Outputs: Supports charging several devices simultaneously via USB-A and USB-C. Solar Power Support: Ability to recharge via solar panels for complete sustainability.\",\"descriptionAr\":\"Enjoy reliable power anywhere with the Anker SOLIX C200 DC Portable Power Station. With durable LiFePO4 batteries and a compact design, this station provides continuous energy for your smartphones, cameras, and laptops, making it the perfect companion for trips and outdoor adventures. The Anker SOLIX C200 DC features advanced LiFePO4 battery technology that lasts up to 10 years of daily use, offering exceptional safety and sustainability. With a 185Wh capacity, it gives you the power to charge your devices multiple times, while the 100W USB-C port ensures ultra-fast charging for laptops and phones. The device is designed to be portable and lightweight, featuring a smart display that shows remaining power and charging speeds. Additionally, the station supports solar charging, allowing you to recharge in locations without traditional power sources, so you always stay connected. Key Features Long-Lasting LiFePO4 Battery: 10-year lifespan with consistent high performance. 100W Fast Charging: Bi-directional USB-C port charges your devices and the station itself rapidly. 185Wh Capacity: Ample power to charge phones, tablets, and cameras for several days. Compact & Durable Design: Lightweight with a robust build to withstand outdoor impacts. Multiple Inputs/Outputs: Supports charging several devices simultaneously via USB-A and USB-C. Solar Power Support: Ability to recharge via solar panels for complete sustainability.\"}]}"', '2026-03-11T02:36:59.132161', '2026-05-10T12:38:32.643');
INSERT INTO "homepage_sections" ("id", "type", "title_ar", "title_en", "language", "sort_order", "visible", "metadata", "created_at", "updated_at") VALUES ('e39637b7-f855-4e5f-b680-4313b73a6b67', 'product_slider', NULL, NULL, 'both', 32, TRUE, '{"products":[{"handle":"jbl-tour-one-m2","titleEn":"JBL Tour One M2 — Wireless Over-Ear Headphones with Adaptive Noise Cancelling","titleAr":"سماعة JBL Tour One M2 — سماعة رأس لاسلكية مع عزل ضوضاء متكيف","vendor":"JBL","imageUrl":"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/17589044671773240047-800x800.webp?v=1766932202&width=600&quality=75","price":"235.0","compareAtPrice":"280.0","currency":"JOD","description":"Wireless over-ear headphones designed to deliver immersive sound with adaptive noise cancelling and all-day comfort. The JBL Tour One M2 headphones are built for listeners who want high-quality sound and focused listening. With adaptive noise cancelling, they help reduce surrounding noise for a more immersive audio experience. Designed for long listening sessions, the over-ear fit provides comfort and stability, making the Tour One M2 suitable for travel, work, and everyday use. Key Features Adaptive Noise Cancelling: Designed to reduce external noise for focused listening. Wireless over-ear design: Provides comfort and immersive sound coverage. High-quality JBL sound: Engineered for clear and detailed audio performance. Everyday versatility: Suitable for travel, work, and daily listening. Technical Specifications Brand JBL Product Name JBL Tour One M2 Product Type Wireless over-ear headphones Noise Cancelling Adaptive Noise Cancelling Use Case Music, travel, work, and everyday listening Order Now — Available in Jordan","descriptionAr":"سماعة رأس لاسلكية بتصميم فوق الأذن توفر تجربة استماع غامرة مع عزل ضوضاء متكيف وراحة للاستخدام الطويل. سماعة JBL Tour One M2 مصممة لعشاق الصوت الذين يبحثون عن تجربة استماع مركزة. توفر تقنية عزل الضوضاء المتكيف تقليلًا للأصوات المحيطة لمزيد من التركيز. بفضل تصميمها فوق الأذن، توفر السماعة راحة وثباتًا أثناء الاستخدام، مما يجعلها مناسبة للسفر والعمل والاستخدام اليومي. المميزات الرئيسية عزل ضوضاء متكيف: يساعد على تقليل الأصوات الخارجية لتجربة استماع مركزة. تصميم فوق الأذن لاسلكي: يوفر راحة وصوتًا غامرًا. صوت JBL عالي الجودة: مصمم لتقديم صوت واضح وغني. مناسبة للاستخدام اليومي: مثالية للسفر والعمل والاستماع اليومي. المواصفات التقنية العلامة التجارية JBL اسم المنتج JBL Tour One M2 نوع المنتج سماعة رأس لاسلكية فوق الأذن عزل الضوضاء عزل ضوضاء متكيف الاستخدام الموسيقى، السفر، العمل، الاستخدام اليومي اطلبه الآن — متوفر في الأردن"},{"handle":"anker-soundcore-life-q30-hybrid-active-noise-cancelling-headphones","titleEn":"Anker Soundcore Life Q30 Hybrid Active Noise Cancelling Headphones","titleAr":"سماعات أنكر ساوندكور لايف Q30 لإلغاء الضوضاء\n","vendor":"Anker","imageUrl":"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/UGREEN_20_000mAh_Power_Bank_30W_PD_Fast_Charging_with_Built-in_USB-C_Cable_Digital_Display_-_2026-04-21T154821.283.png?v=1776775744&width=600&quality=75","price":"59.0","compareAtPrice":"79.0","currency":"JOD","description":"Description: The Anker Soundcore Life Q30 headphones offer an immersive audio experience with advanced hybrid active noise cancellation. Equipped with 40mm silk diaphragm drivers, they deliver high-resolution sound with robust bass and clear treble. The headphones feature multiple noise cancellation modes tailored for different environments, ensuring optimal listening in various settings. Key Features: Hybrid Active Noise Cancellation with multiple modes Hi-Res Audio with 40mm silk diaphragm drivers Up to 40 hours of playtime in noise cancelling mode; 60 hours in standard mode Fast charging: 5 minutes provides 4 hours of playback Comfortable fit with memory foam ear cups Multi-point connection for seamless device switching Specifications: Dimensions: 195 × 180 × 78 mm Weight: 260 g Material: Plastic with memory foam ear cups Color Options: Black, Blue, Pink Power Requirements: USB-C charging Other Specs: Bluetooth Version: 5.0 Frequency Response: 16 Hz - 40 kHz Impedance: 16 Ω Sensitivity: 95 dB Microphone: Yes Connection: Bluetooth and 3.5mm AUX","descriptionAr":"الوصف:توفر سماعات أنكر ساوندكور لايف Q30 تجربة صوتية غامرة بفضل تقنية إلغاء الضوضاء النشط الهجين المتطورة. مزودة بمحركات بحجم 40 ملم بغطاء حريري، مما يضمن جودة صوت عالية الوضوح مع جهير قوي وصوتيات دقيقة. تتميز السماعات بوضعيات متعددة لإلغاء الضوضاء، مما يجعلها مثالية لمختلف البيئات والاستعمالات. المميزات الرئيسية: تقنية إلغاء الضوضاء النشط الهجين مع أوضاع متعددة صوت عالي الدقة (Hi-Res Audio) مع محركات 40 ملم تشغيل يصل إلى 40 ساعة في وضع إلغاء الضوضاء و60 ساعة في الوضع العادي شحن سريع: 5 دقائق شحن تمنحك 4 ساعات من التشغيل تصميم مريح مع وسائد أذن من الفوم الميموري اتصال متعدد النقاط لتبديل سلس بين الأجهزة المواصفات: الأبعاد: 195 × 180 × 78 ملم الوزن: 260 جرام المادة: بلاستيك مع وسائد أذن من الفوم الميموري خيارات الألوان: أسود، أزرق، وردي متطلبات الطاقة: شحن عبر منفذ USB-C مواصفات إضافية: إصدار البلوتوث: 5.0 استجابة التردد: 16 هرتز – 40 كيلوهرتز المقاومة: 16 أوم الحساسية: 95 ديسيبل ميكروفون: نعم الاتصال: بلوتوث + منفذ AUX مقاس 3.5 ملم","subtitleAr":"توفر سماعات أنكر ساوندكور لايف Q30 تجربة صوتية غامرة بفضل تقنية إلغاء الضوضاء النشط الهجين المتطورة. مزودة بمحركات بحجم 40 ملم بغطاء حريري، مما يضمن جودة صوت عالية الوضوح مع جهير قوي وصوتيات دقيقة. تتميز السماعات بوضعيات متعددة لإلغاء الضوضاء، مما يجعلها مثالية لمختلف البيئات والاستعمالات. المميزات الرئيسية: تقنية إلغاء الضوضاء النشط الهجين مع أوضاع متعددة صوت عالي الدقة (Hi-Res Audio) مع محركات 40 ملم تشغيل يصل إلى 40 ساعة في وضع إلغاء الضوضاء و60 ساعة في الوضع العادي شحن سريع: 5 دقائق شحن تمنحك 4 ساعات من التشغيل تصميم مريح مع وسائد أذن من الفوم الميموري اتصال متعدد النقاط لتبديل سلس بين الأجهزة المواصفات: الأبعاد: 195 × 180 × 78 ملم الوزن: 260 جرام المادة: بلاستيك مع وسائد أذن من الفوم الميموري خيارات الألوان: أسود، أزرق، وردي متطلبات الطاقة: شحن عبر منفذ USB-C مواصفات إضافية: إصدار البلوتوث: 5.0 استجابة التردد: 16 هرتز – 40 كيلوهرتز المقاومة: 16 أوم الحساسية: 95 ديسيبل ميكروفون: نعم الاتصال: بلوتوث + منفذ AUX مقاس 3.5 ملم","customTitleAr":"ساوندكور Q30 إلغاء الضوضاء"},{"handle":"anker-soundcore-rave-3s-200w-party-speaker-wireless-mics","titleEn":"Anker Soundcore Rave 3S AI Party Speaker - 200W Output - 2 Wireless Microphones Included - AI Vocal Removal & Reverb - Immersive Light Show - 12-Hour Playtime - Portable Bluetooth PA System","titleAr":"مكبر صوت أنكر ساوند كور (Soundcore Rave 3S) بقوة 200 واط - نظام حفلات ذكي مع ميكروفونين لاسلكيين - ميزة إزالة الصوت بالذكاء الاصطناعي - عرض أضواء مدمج - بطارية 12 ساعة","vendor":"Anker","imageUrl":"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/712S1bN5scL._AC_SL1500_-1200x1200.webp?v=1769618896&width=600&quality=75","price":"225.0","compareAtPrice":"239.0","currency":"JOD","description":"The Anker Soundcore Rave 3S is a powerhouse 200W portable party speaker designed for ultimate entertainment. Featuring two wireless microphones and innovative AI vocal removal technology, it transforms any song into a karaoke track, making it the perfect choice for home parties, backyards, and events. Take your celebrations to the next level with the Soundcore Rave 3S. Delivering an impressive 200W of thunderous sound, this speaker ensures your music is heard with clarity and deep, punchy bass. The standout feature is the AI-driven vocal removal, which intelligently strips the vocals from almost any song, allowing you to take center stage with the included dual wireless microphones. With built-in reverb effects, your voice will sound professional and polished. The Rave 3S isn''t just about sound; it creates a complete atmosphere with a dynamic light show that syncs perfectly to the beat of your music. Designed for portability, it features a rugged handle and up to 12 hours of continuous playtime on a single charge. Whether you are hosting a karaoke night or a backyard BBQ, the Rave 3S provides a professional PA system experience with the reliability of Soundcore’s advanced Bluetooth technology. Key Features 200W Powerful Sound: Fills even large outdoor spaces with rich, high-fidelity audio and heavy bass. Dual Wireless Microphones: High-quality mics included for seamless duets and professional presentations. AI Vocal Removal: Advanced technology that removes vocals from your favorite tracks for instant karaoke. 12-Hour Playtime: Long-lasting battery ensures the music keeps going from day to night. Dynamic Light Show: Multi-color LEDs that pulse and change with the rhythm to enhance the party vibe. Technical Specifications Brand Soundcore by Anker Model Rave 3S Power Output 200W Max Microphones 2x Wireless Mics Included Battery Life Up to 12 Hours Special Features AI Vocal Removal, Reverb Control, Light Show Connectivity Bluetooth, AUX, USB","descriptionAr":"يعد Anker Soundcore Rave 3S مكبراً صوتياً محمولاً بقوة 200 واط مصمماً للترفيه الفائق. بفضل الميكروفونين اللاسلكيين وتقنية إزالة الصوت المبتكرة بالذكاء الاصطناعي، فإنه يحول أي أغنية إلى مسار كاريوكي، مما يجعله الخيار الأمثل للحفلات المنزلية والفعاليات الخارجية. ارتقِ باحتفالاتك إلى المستوى التالي مع سماعة Soundcore Rave 3S. من خلال تقديم صوت قوي بقدرة 200 واط، يضمن هذا المكبر سماع موسيقاك بوضوح تام مع \"باس\" عميق وقوي. الميزة الأبرز هي إزالة الصوت بالذكاء الاصطناعي، والتي تعمل بذكاء على تجريد الغناء من أي أغنية تقريباً، مما يسمح لك باعتلاء المسرح باستخدام الميكروفونات اللاسلكية المزدوجة المرفقة. مع تأثيرات الصدى (Reverb) المدمجة، سيظهر صوتك بشكل احترافي ومصقول. لا يقتصر Rave 3S على الصوت فحسب؛ بل يخلق أجواءً متكاملة مع عرض ضوئي ديناميكي يتزامن تماماً مع إيقاع الموسيقى. تم تصميمه ليكون سهل النقل بفضل المقبض المتين، كما يوفر ما يصل إلى 12 ساعة من التشغيل المتواصل بشحنة واحدة. سواء كنت تستضيف ليلة كاريوكي أو حفلة شواء في الحديقة، يوفر لك Rave 3S تجربة نظام صوتي احترافي مع موثوقية تقنية البلوتوث المتقدمة من ساوند كور. الميزات الرئيسية صوت قوي 200 واط: يملأ المساحات الخارجية الكبيرة بصوت عالي الدقة وتفاصيل غنية. ميكروفونين لاسلكيين: ميكروفونات عالية الجودة مرفقة للغناء الثنائي والعروض التقديمية الاحترافية. إزالة الصوت بالذكاء الاصطناعي: تقنية متطورة تزيل أصوات المغنين من أغانيك المفضلة للكاريوكي الفوري. تشغيل لمدة 12 ساعة: بطارية تدوم طويلاً تضمن استمرار الحفلة من النهار حتى الليل. عرض أضواء ديناميكي: مصابيح LED متعددة الألوان تنبض مع الإيقاع لتعزيز أجواء الحفلة. المواصفات التقنية العلامة التجاريةساوند كور من أنكر (Soundcore by Anker) الموديلRave 3S قوة الخرج200 واط كحد أقصى الميكروفوناتميكروفونين لاسلكيين مرفقين عمر البطاريةحتى 12 ساعة ميزات خاصةإزالة الصوت بالذكاء الاصطناعي، تحكم بالصدى، عرض أضواء الاتصالبلوتوث، AUX، USB","customTitleAr":"ساوندكور Rave 3s"},{"handle":"anker-soundcore-space-q45-adaptive-active-noise-cancelling-headphones","titleEn":"Anker Soundcore Space Q45 Adaptive Active Noise Cancelling Headphones","titleAr":"سماعات أنكر ساوندكور سبيس Q45 بإلغاء الضوضاء التكيفي\n","vendor":"Anker","imageUrl":"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/download-2025-02-26T230016.438.webp?v=1776776695&width=600&quality=75","price":"79.0","compareAtPrice":"99.0","currency":"JOD","description":"Description: The Anker Soundcore Space Q45 headphones offer advanced adaptive active noise cancellation, reducing ambient noise by up to 98%. With a 50-hour playtime, Hi-Res Audio Wireless certification, and Bluetooth 5.3 connectivity, they provide an immersive and uninterrupted listening experience. Key Features: Adaptive Active Noise Cancellation Up to 50 Hours Playtime Hi-Res Audio Wireless with LDAC Support Bluetooth 5.3 Connectivity Multipoint Connection Fast Charging: 5 Minutes for 4 Hours Playtime Comfortable Design with Memory Foam Ear Cups Specifications: Dimensions: Length: 161mm; Height: 190mm; Width: 88mm Weight: Approximately 281g Material: Memory foam ear cups with adjustable headband Color Options: Black Power Requirements: USB-C charging; 5V⎓0.7A input Other Specs: 40mm drivers; supports SBC, AAC, and LDAC codecs","descriptionAr":"الوصف:سماعات أنكر ساوندكور سبيس Q45 توفر إلغاء ضوضاء تكيفي متطور يقلل من الضوضاء المحيطة بنسبة تصل إلى 98%. تتميز بعمر بطارية يصل إلى 50 ساعة، وشهادة صوت عالي الدقة Hi-Res Audio Wireless، واتصال بلوتوث 5.3 لتجربة استماع غامرة بدون انقطاع. المميزات الرئيسية: إلغاء ضوضاء تكيفي متقدم عمر بطارية يصل إلى 50 ساعة صوت عالي الدقة مع دعم LDAC تقنية بلوتوث 5.3 لاتصال مستقر إمكانية الاتصال بجهازين في وقت واحد شحن سريع: 5 دقائق تمنحك 4 ساعات من التشغيل تصميم مريح مع وسادات أذن من الفوم الميموري المواصفات: الأبعاد: الطول: 161 ملم؛ الارتفاع: 190 ملم؛ العرض: 88 ملم الوزن: حوالي 281 جرام المادة: وسائد أذن من الفوم الميموري مع طوق رأس قابل للتعديل خيارات الألوان: أسود متطلبات الطاقة: شحن عبر USB-C، إدخال 5V⎓0.7A مواصفات إضافية: مشغلات صوت 40 ملم؛ دعم ترميز SBC، AAC، وLDAC","customTitleAr":"ساوندكور Q45"},{"handle":"soundcore-liberty-5-premium-hi-res-noise-cancelling-earbuds-black","titleEn":"Soundcore Liberty 5 True Wireless Earbuds by Anker - Advanced ACAA Coaxial Acoustic System - Hi-Res Audio - Ultra-Fast Charging - Personalized Noise Cancelling","titleAr":"سماعات ساوند كور (Soundcore Liberty 5) من أنكر - صوت عالي الدقة Hi-Res - نظام ACAA الصوتي المطور - عزل ضوضاء متكيف ","vendor":"Anker","imageUrl":"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/A3957Z11_DTC_listing_image_TD01_US_V1_3838x_a4935773-d35e-4631-b28a-b8dacbd7184c.webp?v=1769618280&width=600&quality=75","price":"77.0","compareAtPrice":"89.0","currency":"JOD","description":"The Soundcore Liberty 5 represents the next evolution in premium audio technology, featuring an upgraded ACAA coaxial acoustic system for unparalleled sound depth. With next-generation noise cancelling and high-resolution audio support, these earbuds are designed for the ultimate audiophile experience. Immerse yourself in a world of pure, detailed sound with the Soundcore Liberty 5 by Anker. These flagship earbuds utilize a refined coaxial acoustic design to deliver rich mids, sparkling highs, and a deep, resonance-filled bass. Supporting LDAC technology, the Liberty 5 provides a high-resolution wireless audio experience that stays true to the original studio recording, ensuring every note is heard with absolute clarity. Connectivity and comfort reach new heights with the Liberty 5. Featuring advanced sensors that adapt to your ear canal, the noise cancelling system intelligently blocks out ambient sounds tailored specifically to your environment. The sleek, ergonomic design is complemented by an extended battery life and ultra-fast charging capabilities, allowing you to enjoy hours of music with just a few minutes of power. Whether you are on a flight or in a busy office, the Liberty 5 ensures your audio remains uninterrupted and professional. Key Features Upgraded ACAA System: Advanced coaxial architecture for superior sound balance and clarity across all frequencies. Hi-Res Audio Wireless: Supports LDAC technology for a 3x higher data transmission rate compared to standard Bluetooth. Personalized ANC: Adaptive noise cancelling that tunes itself to your specific ear shape and surroundings. Crystal-Clear Calls: Multi-microphone array with AI-driven noise reduction for high-quality voice pickup. Long-Lasting Battery: Designed for extended use with fast-charging support via USB-C or wireless chargers. Technical Specifications Brand Soundcore by Anker Model Liberty 5 Audio Formats LDAC, Hi-Res Wireless, AAC, SBC Noise Cancelling Adaptive Active Noise Cancelling (ANC) Connectivity Bluetooth 5.3 (Multipoint) Charging USB-C & Wireless Charging Support Color Black\\White","descriptionAr":"تمثل سماعة Soundcore Liberty 5 التطور التالي في تكنولوجيا الصوت المتميزة، حيث تتميز بنظام صوتي محوري ACAA مطور لعمق صوتي لا مثيل له. مع الجيل الجديد من عزل الضوضاء ودعم الصوت عالي الدقة، تم تصميم هذه السماعات لتوفير أفضل تجربة استماع للمحترفين. انغمس في عالم من الصوت النقي والمفصل مع سماعات ساوند كور Liberty 5 من أنكر. تستخدم هذه السماعات الرائدة تصميماً صوتياً محورياً دقيقاً لتقديم ترددات متوسطة غنية، وترددات عالية ساطعة، وباس عميق يتردد صداه بوضوح. بفضل دعم تقنية LDAC، توفر Liberty 5 تجربة صوتية لاسلكية عالية الدقة تظل وفية لتسجيل الاستوديو الأصلي، مما يضمن سماع كل نوتة بوضوح تام. تصل الراحة والاتصال إلى آفاق جديدة مع Liberty 5. تتميز السماعة بمستشعرات متطورة تتكيف مع قناة الأذن الخاصة بك، حيث يعمل نظام إلغاء الضوضاء بذكاء على حجب الأصوات المحيطة بما يتناسب تماماً مع بيئتك. يكتمل التصميم المريح والأنيق بعمر بطارية ممتد وقدرات شحن فائقة السرعة، مما يتيح لك الاستمتاع بساعات من الموسيقى بشحنها لعدة دقائق فقط. سواء كنت في رحلة طيران أو في مكتب مزدحم، تضمن لك Liberty 5 بقاء صوتك دون انقطاع وبجودة احترافية. الميزات الرئيسية نظام ACAA المطور: هندسة محورية متقدمة لتوازن صوتي فائق ووضوح عبر جميع الترددات. صوت عالي الدقة لاسلكي (Hi-Res): يدعم تقنية LDAC لنقل بيانات أسرع بـ 3 مرات من البلوتوث القياسي. إلغاء ضوضاء مخصص: تقنية ANC تكيفية تضبط نفسها وفقاً لشكل أذنك والبيئة المحيطة. مكالمات واضحة تماماً: مصفوفة ميكروفونات متعددة مع تقليل ضوضاء مدعوم بالذكاء الاصطناعي. بطارية تدوم طويلاً: مصممة للاستخدام الممتد مع دعم الشحن السريع عبر USB-C أو الشواحن اللاسلكية. المواصفات التقنية العلامة التجارية ساوند كور من أنكر (Soundcore by Anker) الموديل Liberty 5 تنسيقات الصوت LDAC, Hi-Res Wireless, AAC, SBC إلغاء الضوضاء إلغاء ضوضاء نشط تكيفي (ANC) الاتصال بلوتوث 5.3 (اتصال متعدد النقاط) الشحن يدعم USB-C والشحن اللاسلكي اللون أسود/ابيض"},{"handle":"anker-soundcore-space-one-pro-black","titleEn":"Anker Soundcore Space One Pro","titleAr":"سماعات أنكر ساوندكور سبيس وان برو  ","vendor":"Anker","imageUrl":"https://cdn.shopify.com/s/files/1/0668/2837/0083/files/download-2025-02-26T235534.308.webp?v=1743847188&width=600&quality=75","price":"95.0","compareAtPrice":"105.0","currency":"JOD","description":"Description: The Anker Soundcore Space One Pro is a premium over-ear wireless headphone designed for commuters and audiophiles. It features advanced adaptive active noise cancellation, a super foldable design for portability, and delivers high-resolution, distortion-free audio. Key Features: Adaptive Active Noise Cancelling: Utilizes a 4-stage noise-cancelling system to eliminate ambient noise in real-time, ensuring an immersive listening experience. Super Foldable Design: Incorporates the Soundcore-engineered FlexiCurve™ structure, reducing the headphone''s size by 50% for easy storage and portability. High-Resolution Audio: Equipped with drivers featuring triple composite diaphragms, delivering Hi-Res audio with minimal distortion. Extended Battery Life: Offers up to 40 hours of playback with noise cancellation enabled and up to 60 hours without. A quick 5-minute charge provides an additional 8 hours of listening time. Comfortable Fit: Designed with a pressure-relieving headband and soft earcups for prolonged comfort during extended listening sessions. Specifications: Weight: Approximately 286 grams Material: Durable plastic with soft cushioning Color Options: Jet Black / White Power Requirements: Rechargeable battery via USB-C port Other Specs: Bluetooth Version: 5.3 Driver Size: 40 mm Playback Time: 40 hours (ANC on), 60 hours (ANC off) Charging Time: Full charge in 2 hours Audio Codecs: Supports LDAC for high-resolution wireless audio Microphones: 6 integrated mics for enhanced call quality and noise cancellation","descriptionAr":"الوصف:سماعات أنكر ساوندكور سبيس وان برو هي سماعات رأس لاسلكية فاخرة مخصصة للمسافرين وعشاق الصوتيات. تتميز بتقنية إلغاء الضوضاء النشط التكيفي، وتصميم قابل للطي لسهولة الحمل، كما توفر صوتًا عالي الدقة بدون تشويش. المميزات الرئيسية: إلغاء الضوضاء النشط التكيفي: تعتمد على نظام مكون من 4 مراحل لتقليل الضوضاء المحيطة في الوقت الفعلي، مما يمنحك تجربة استماع غامرة. تصميم قابل للطي: تعتمد تقنية FlexiCurve™ الخاصة بـ Soundcore، مما يقلل حجم السماعات بنسبة 50% لتسهيل التخزين والحمل. صوت عالي الدقة: مزودة بمحركات ذات أغشية مركبة ثلاثية الطبقات، مما يوفر صوتًا عالي الجودة مع تشويش منخفض. عمر بطارية طويل: تصل مدة التشغيل إلى 40 ساعة عند تفعيل إلغاء الضوضاء و60 ساعة عند إيقافه. شحن سريع لمدة 5 دقائق يمنحك 8 ساعات تشغيل إضافية. راحة مثالية: تصميم مريح مع طوق رأس يقلل الضغط وسائد أذن ناعمة توفر راحة طويلة الأمد خلال فترات الاستماع الممتدة. المواصفات: الوزن: حوالي 286 جرام المادة: بلاستيك متين مع وسائد مريحة خيارات الألوان: أبيض/ أسود جت متطلبات الطاقة: بطارية قابلة لإعادة الشحن عبر منفذ USB-C مواصفات إضافية: إصدار البلوتوث: 5.3 حجم المشغل الصوتي: 40 ملم مدة التشغيل: 40 ساعة (مع تشغيل إلغاء الضوضاء) – 60 ساعة (بدون إلغاء الضوضاء) مدة الشحن: شحن كامل في ساعتين ترميز الصوت: يدعم LDAC للحصول على صوت عالي الدقة عبر البلوتوث الميكروفونات: تحتوي على 6 ميكروفونات مدمجة لتحسين جودة المكالمات وإلغاء الضوضاء"}]}', '2026-03-12T00:46:24.189501', '2026-05-10T12:44:35.481');
